/* Forms */
function formHTML(key,hid={},skip=[],def={}){const F=FM[key];
 const h=Object.entries(hid).map(([k,v])=>`<input type="hidden" name="${k}" value="${E(v)}">`).join('');
 const f=F.f.filter(x=>!skip.includes(x[0])).map(([n,l,t,r,x,full])=>{const id=key+'-'+n,req=r?' required':'',lab=`${l}${r?'':''}`;
  let c;if(t==='textarea')c=`<textarea id="${id}" name="${n}" rows="4"${req} placeholder="${E(x||'')}"></textarea>`;
  else if(t==='select')c=`<select id="${id}" name="${n}"${req}><option value="">Select${r?'':' (optional)'}</option>${x.map(o=>`<option${def[n]===o?' selected':''}>${E(o)}</option>`).join('')}</select>`;
  else if(t==='file')c=`<input id="${id}" type="file" name="${n}" accept=".pdf,.doc,.docx"${req}>`;
  else c=`<input id="${id}" type="${t}" name="${n}"${req} placeholder="${E(x||'')}">`;
  return `<label for="${id}" class="${full||t==='textarea'||t==='file'?'full':''}">${l}${r?' *':''}${c}</label>`}).join('');
 return `<div class="formbox" data-fb="${key}"><form id="f-${key}" data-key="${key}" enctype="multipart/form-data" novalidate><input type="hidden" name="form-name" value="${F.id}"><p class="hp" aria-hidden="true"><label>Leave empty<input name="bot-field" tabindex="-1" autocomplete="off"></label></p>${h}<div class="ff">${f}</div><button class="btn navy" type="submit">${F.s}</button><p class="note">Required fields are marked *. Your enquiry is sent directly to ${EM}.</p><div class="out" aria-live="polite"></div></form></div>`}
async function doForm(f){
 const key=f.dataset.key,F=FM[key],out=$('.out',f),b=$('button[type=submit]',f);
 for(const x of f.querySelectorAll('[required]')){const v=x.type==='file'?(x.files[0]?'x':''):x.value.trim();
  if(!v||(x.type==='email'&&!/^\S+@\S+\.\S+$/.test(v))){out.innerHTML=`<div class="msg err" role="alert">Please complete the required fields${x.type==='email'?' with a valid email address':''}.</div>`;x.focus();return}
  if(x.type==='file'&&x.files[0].size>5*1024*1024){out.innerHTML='<div class="msg err" role="alert">That file is larger than 5 MB. Please choose a smaller file.</div>';return}}
 const fd=new FormData(f),hasFile=[...fd.values()].some(v=>v instanceof File&&v.name);
 b.disabled=true;b.textContent='Sending…';
 try{let res;
  if(hasFile)res=await fetch('/',{method:'POST',body:fd});
  else{const o={};fd.forEach((v,k)=>{if(!(v instanceof File))o[k]=v});res=await fetch('/',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(o).toString()})}
  if(!res.ok)throw 0;
  f.parentNode.innerHTML=`<div class="msg" role="status"><h3>Thank you</h3><p>${F.ok}</p><a class="btn sm" href="#/">Back to home</a></div>`;
 }catch(e){b.disabled=false;b.textContent=F.s;
  const txt=[...fd.entries()].filter(([k,v])=>!(v instanceof File)&&k!=='bot-field'&&k!=='form-name'&&v).map(([k,v])=>k+': '+v).join('\n');
  out.innerHTML=`<div class="msg err" role="alert"><b>We couldn’t send this automatically.</b> Please send it to us directly:<br><br><a class="btn sm" target="_blank" rel="noopener" href="https://wa.me/${WA}?text=${encodeURIComponent(F.id+'\n'+txt)}">WhatsApp</a> <a class="btn sm ghost" href="mailto:${EM}?subject=${encodeURIComponent(F.id)}&body=${encodeURIComponent(txt)}">Email</a></div>`}}

